import json, os, math
# Note numbers: C-4 = 49, hence MIDI 60 -> 49.
def nn(m): return int(m)-11
NOTE_OFF=97
P=24
# 0 kick, 1 snare, 2 clap, 3 CH, 4 OH, 5 ride/tom, 6 bass,
# 7-9 chord voices, 10 arp, 11 lead, 12 lead echo/harmony,
# 13/14 stereo pads, 15 fx, 16 pluck, 17 sparkle
C=dict(kick=0,snare=1,clap=2,ch=3,oh=4,perc=5,bass=6,c1=7,c2=8,c3=9,arp=10,lead=11,lead2=12,padl=13,padr=14,fx=15,pluck=16,sparkle=17)
I=dict(kick=1,snare=2,clap=3,ch=4,oh=5,ride=6,bass=7,chord=8,arp=9,lead=10,padl=11,padr=12,pluck=13,riser=14,impact=15,tom=16)
CH={
 'Am':dict(bass=45,notes=[57,60,64]),
 'F':dict(bass=41,notes=[53,57,60]),
 'C':dict(bass=48,notes=[60,64,67]),
 'G':dict(bass=43,notes=[55,59,62]),
 'Dm':dict(bass=38,notes=[50,53,57]),
 'Em':dict(bass=40,notes=[52,55,59]),
 'E':dict(bass=40,notes=[52,56,59]),
}
PROG_A=['Am','F','C','G']
PROG_B=['Dm','Am','F','G']
PROG_C=['F','G','C','Am']
PROG_D=['F','G','Am','E']
PROG_BUILD=['Dm','Am','F','G']
PROG_BRIDGE=['Dm','G','C','E']
PROG_BUILD2=['Dm','E','Am','Am']
calls=[]
def add(name,**args):
    calls.append(dict(name=name,arguments=args))
def cell(p,r,ch,note=None,ins=None,vol=None,eff=None,par=None):
    a=dict(pattern=p,row=int(r),channel=int(ch))
    if note is not None:a['note']=int(note) if not isinstance(note,str) else note
    if ins is not None:a['instrument']=int(ins)
    if vol is not None:a['volume']=int(vol)
    if eff is not None:a['effect']=int(eff)
    if par is not None:a['effect_param']=int(par)
    add('pattern_set_cell',**a)

def note(p,r,ch,midi,ins,vol,pan=None):
    cell(p,r,ch,note=nn(midi),ins=ins,vol=vol,eff=8 if pan is not None else None,par=pan)

def noteoff(p,r,ch):
    cell(p,r,ch,note=NOTE_OFF)

def pad_bar(p,b,ch,vol=22,sustain=True,stabvol=18):
    d=CH[ch]; r=b*16
    note(p,r,C['padl'],d['notes'][0],I['padl'],vol)
    note(p,r,C['padr'],d['notes'][2],I['padr'],vol)
    if sustain:
        for key,m in zip(('c1','c2','c3'),d['notes']):
            note(p,r,C[key],m,I['chord'],stabvol,pan={'c1':104,'c2':128,'c3':152}[key])

def stab(p,r,ch,vol=28):
    d=CH[ch]
    for key,m,pan in zip(('c1','c2','c3'),d['notes'],(104,128,152)):
        note(p,r,C[key],m,I['chord'],vol,pan=pan)

def bass_bar(p,b,ch,style='roll',vol=48,octave=0):
    root=CH[ch]['bass']+octave; r=b*16
    if style=='none': return
    if style=='soft':
        seq=[(0,0,48),(6,0,40),(8,12,32),(12,0,44)]
    elif style=='half':
        seq=[(0,0,46),(6,7,34),(8,0,42),(12,12,30)]
    elif style=='pedal':
        seq=[(0,0,46),(4,0,38),(8,0,46),(12,0,38)]
    elif style=='sync':
        seq=[(0,0,48),(3,12,31),(4,0,44),(6,7,34),(8,0,48),(10,12,32),(11,7,32),(12,0,44),(14,12,30)]
    else:
        seq=[(0,0,48),(2,12,30),(4,0,44),(6,12,30),(8,0,48),(10,7,34),(12,0,44),(14,12,30)]
    for off,iv,v in seq:
        note(p,r+off,C['bass'],root+iv,I['bass'],max(12,int(vol*v/48)))

def arp_bar(p,b,ch,step=2,vol=28,offset=0):
    ns=CH[ch]['notes']
    pattern=[ns[0]+12,ns[1]+12,ns[2]+12,ns[0]+24,ns[1]+12,ns[2]+12,ns[1]+24,ns[0]+12]
    r=b*16
    for j in range(0,16,step):
        m=pattern[(j//step+offset)%len(pattern)]
        v=vol if (j//step)%2==0 else int(vol*.70)
        note(p,r+j,C['arp'],m,I['arp'],v)

def pluck_bar(p,b,ch,step=4,vol=22,high=12):
    ns=CH[ch]['notes']; r=b*16
    pattern=[ns[0]+high,ns[1]+high,ns[2]+high,ns[1]+high]
    for j in range(0,16,step):
        note(p,r+j,C['pluck'],pattern[(j//step)%4],I['pluck'],vol if j%8==0 else int(vol*.75))

def drums(p,bars=4,style='full',fill=True,ride=False):
    for b in range(bars):
        r=b*16
        if style=='soft':
            kick=[(0,40),(8,34)]
            if b>=2: kick += [(4,26)]
            for off,v in kick: note(p,r+off,C['kick'],nn(60),I['kick'],v)
            for off in [2,6,10,14]:
                note(p,r+off,C['ch'],nn(60),I['ch'],18)
            if b>=2:
                for off in [4,12]: note(p,r+off,C['snare'],nn(60),I['snare'],30)
        elif style=='half':
            for off,v in [(0,40),(8,32)]: note(p,r+off,C['kick'],nn(60),I['kick'],v)
            for off in [4,12]: note(p,r+off,C['snare'],nn(60),I['snare'],28)
            for off in [2,6,10,14]: note(p,r+off,C['ch'],nn(60),I['ch'],16)
        elif style=='build':
            for off in [0,4,8,12]: note(p,r+off,C['kick'],nn(60),I['kick'],42)
            for off in [2,6,10,14]:
                note(p,r+off,C['ch'],nn(60),I['ch'],19)
                note(p,r+off,C['oh'],nn(60),I['oh'],16)
            if b<3:
                for off in [4,12]: note(p,r+off,C['snare'],nn(60),I['snare'],32)
            else:
                for off in [8,10,12,13,14,15]: note(p,r+off,C['snare'],nn(60),I['snare'],28+off-8)
        elif style=='sparse':
            for off in [0,8]: note(p,r+off,C['kick'],nn(60),I['kick'],34)
            for off in [4,12]: note(p,r+off,C['snare'],nn(60),I['snare'],24)
            for off in [2,10]: note(p,r+off,C['ch'],nn(60),I['ch'],15)
        else:
            # Four on the floor with a small skip before beats two/four.
            for off,v in [(0,46),(4,43),(8,46),(12,43)]: note(p,r+off,C['kick'],nn(60),I['kick'],v)
            for off in [4,12]:
                note(p,r+off,C['snare'],nn(60),I['snare'],34)
                note(p,r+off,C['clap'],nn(60),I['clap'],22)
            for off in range(0,16,2):
                note(p,r+off,C['ch'],nn(60),I['ch'],18 if off%4==0 else 23)
            for off in [2,6,10,14]: note(p,r+off,C['oh'],nn(60),I['oh'],21)
            if ride:
                for off in [0,8]: note(p,r+off,C['perc'],nn(60),I['ride'],16)
        if fill and b==bars-1 and style in ('full','soft'):
            # A short, pitched tom fill, kept away from the very last row.
            for off,m,v in [(11,62,25),(12,59,29),(13,55,28),(14,50,25)]:
