def impact(p,r=0,vol=28): note(p,r,C['fx'],nn(60),I['impact'],vol)
def riser(p,r=32,vol=30): note(p,r,C['fx'],nn(60),I['riser'],vol)

# P0: atmospheric introduction, with the last bar pulling into the pulse.
p=0
impact(p,0,16)
for b,ch in enumerate(PROG_A):
