for b in [2,3]:
    lead_bar(p,b,A[b],C['lead'],30,only=[0,1,2,4,5])
bass_bar(p,3,'G','soft',35)
for r in [48,56]: note(p,r,C['kick'],nn(60),I['kick'],30)
for r in [50,54,58,62]: note(p,r,C['ch'],nn(60),I['ch'],13)
riser(p,40,20)

# P1: pulse and arpeggio entry.
p=1
for b,ch in enumerate(PROG_A):
    pad_bar(p,b,ch,20,False)
    arp_bar(p,b,ch,4 if b==0 else 2,25)
    if b>0: bass_bar(p,b,ch,'roll' if b>=2 else 'soft',43)
    if b>=2:
        for off in [0,8]: note(p,b*16+off,C['kick'],nn(60),I['kick'],36)
    for off in [2,6,10,14]: note(p,b*16+off,C['ch'],nn(60),I['ch'],17)
    if b>=2:
        for off in [4,12]: note(p,b*16+off,C['snare'],nn(60),I['snare'],28)
lead_bar(p,3,A[3],C['lead'],34)

# P2: full groove, leaving room for the melody.
p=2
for b,ch in enumerate(PROG_A):
    pad_bar(p,b,ch,17,False)
    arp_bar(p,b,ch,2,28)
    bass_bar(p,b,ch,'roll',48)
    for off in [0,6,8,14]: stab(p,b*16+off,ch,25)
drums(p,4,'full',True,False)
pluck_bar(p,3,'G',2,16,24)

# P3/P4: first theme and its brighter variation.
for p,echo,harm,step,ride in [(3,False,False,2,False),(4,True,True,1,True)]:
    for b,ch in enumerate(PROG_A):
        pad_bar(p,b,ch,18,False)
        arp_bar(p,b,ch,step,28 if p==3 else 30)
        bass_bar(p,b,ch,'roll' if p==3 else 'sync',48)
        for off in [0,6,8,14]: stab(p,b*16+off,ch,27)
    drums(p,4,'full',True,ride)
    lead_pattern(p,A,46 if p==3 else 48,harm,echo)
    if p==4:
        for b,ch in enumerate(PROG_A): sparkle_bar(p,b,ch,12)

# P5: answering theme.
p=5
for b,ch in enumerate(PROG_B):
    pad_bar(p,b,ch,18,False); arp_bar(p,b,ch,2,28); bass_bar(p,b,ch,'sync',48)
    for off in [0,6,8,14]: stab(p,b*16+off,ch,27)
drums(p,4,'full',True,True)
lead_pattern(p,B,47,True,False)

# P6: transition / breakdown with a rising noise sweep.
p=6
for b,ch in enumerate(PROG_BUILD):
    pad_bar(p,b,ch,17,False); bass_bar(p,b,ch,'pedal',42); arp_bar(p,b,ch,2,23)
    for off in [0,8]: stab(p,b*16+off,ch,22)
drums(p,4,'build',False,False)
riser(p,32,32)
lead_bar(p,3,A[3],C['lead'],31,only=[0,1,2,3,4,5])

# P7/P8: broad second theme.
for p,harm,echo,ride in [(7,False,False,False),(8,True,True,True)]:
    for b,ch in enumerate(PROG_C):
        pad_bar(p,b,ch,18,False); arp_bar(p,b,ch,2 if p==7 else 1,28)
        bass_bar(p,b,ch,'roll' if p==7 else 'sync',48)
        for off in [0,6,8,14]: stab(p,b*16+off,ch,27)
    drums(p,4,'full',True,ride)
    lead_pattern(p,CC,47 if p==7 else 49,harm,echo)
    if p==8:
        for b,ch in enumerate(PROG_C): sparkle_bar(p,b,ch,13)

# P9: breathing space, half-time and glassy plucks.
p=9
impact(p,0,26)
for b,ch in enumerate(PROG_A):
    pad_bar(p,b,ch,25,True,17); bass_bar(p,b,ch,'half',38); pluck_bar(p,b,ch,4,22)
    if b<2: lead_bar(p,b,A[b],C['lead'],33,only=[0,1,3,4])
drums(p,4,'half',False,False)

# P10: rebuild with snare roll and arpeggio acceleration.
p=10
for b,ch in enumerate(PROG_BUILD):
    pad_bar(p,b,ch,17,False); bass_bar(p,b,ch,'pedal',44)
    arp_bar(p,b,ch,4 if b<2 else 1,24+b*2)
    for off in [0,8]: stab(p,b*16+off,ch,22)
drums(p,4,'build',False,False)
riser(p,32,32)
lead_bar(p,3,B[3],C['lead'],35,only=[0,1,2,3,4])

# P11-P13: main reprises, with echo and octave reinforcement.
for p,motif,prog in [(11,A,PROG_A),(12,B,PROG_B),(13,CC,PROG_C)]:
    for b,ch in enumerate(prog):
        pad_bar(p,b,ch,17,False); arp_bar(p,b,ch,1,29); bass_bar(p,b,ch,'sync',49)
        for off in [0,6,8,14]: stab(p,b*16+off,ch,28)
    drums(p,4,'full',True,True)
    lead_pattern(p,motif,48,True,True)

# P14: lift / peak of the first half.
p=14
for b,ch in enumerate(PROG_D):
    pad_bar(p,b,ch,18,False); arp_bar(p,b,ch,1,30); bass_bar(p,b,ch,'sync',50)
    for off in [0,6,8,14]: stab(p,b*16+off,ch,29)
