drums(p,4,'full',True,True)
lead_pattern(p,D,49,True,True,transpose=0)

# P15: bridge, suspended half-time.
p=15
for b,ch in enumerate(PROG_BRIDGE):
    pad_bar(p,b,ch,25,True,18); bass_bar(p,b,ch,'half',39); pluck_bar(p,b,ch,4,23)
    if b%2==0: lead_bar(p,b,BR[b],C['lead'],35)
drums(p,4,'half',False,False)

# P16: final build.
p=16
for b,ch in enumerate(PROG_BUILD2):
    pad_bar(p,b,ch,18,False); bass_bar(p,b,ch,'pedal',44); arp_bar(p,b,ch,1,25+b*2)
    for off in [0,8]: stab(p,b*16+off,ch,23)
drums(p,4,'build',False,False)
riser(p,28,34)
lead_bar(p,3,BR[3],C['lead'],35,only=[0,1,2,3,4])

# P17-P20: climax block.
for p,motif,prog,tr in [(17,A,PROG_A,0),(18,B,PROG_B,0),(19,CC,PROG_C,0),(20,D,PROG_D,0)]:
    for b,ch in enumerate(prog):
        pad_bar(p,b,ch,17,False); arp_bar(p,b,ch,1,30); bass_bar(p,b,ch,'sync',50)
        for off in [0,6,8,14]: stab(p,b*16+off,ch,29)
