p=21
for b,ch in enumerate(PROG_A):
    pad_bar(p,b,ch,20,False); arp_bar(p,b,ch,2,25); bass_bar(p,b,ch,'roll',43)
    for off in [0,8]: stab(p,b*16+off,ch,24)
