# P23: open cadence on E, then a short pause before the loop to Am.
p=23
impact(p,0,20)
for b,ch in enumerate(['F','G','Am','E']):
    if b<3:
        pad_bar(p,b,ch,22,False); bass_bar(p,b,ch,'half',36)
        for off in [0,8]: stab(p,b*16+off,ch,23)
    else:
        bass_bar(p,b,ch,'half',34)
        stab(p,48,'E',24)
    if b<2: pluck_bar(p,b,ch,4,19)
    if b==1: lead_bar(p,b,A[1],C['lead'],31,only=[0,1,3,4])
    if b==2: lead_bar(p,b,A[2],C['lead'],31,only=[0,1,3,4])
# final suspension: B then A over E, released by the following intro's Am
note(p,48,C['lead'],nn(71),I['lead'],29)
note(p,52,C['lead'],nn(76),I['lead'],27)
note(p,56,C['pluck'],nn(69),I['pluck'],20)
for off in [48,50,54]: note(p,off,C['ch'],nn(60),I['ch'],11)

# Build module and all pattern lengths.
add('module_new',channels=18,name='Neon Circuit')
add('song_set',bpm=150,speed=6,length=P,loop_start=0,channels=18)
for p in range(P): add('pattern_set_length',pattern=p,rows=64)
for pos in range(P): add('order_set',position=pos,pattern=pos)
# Load the synthesized, single-sample instruments.
for key,inst in I.items():
    fname={'ch':'ch','oh':'oh','padl':'pad_l','padr':'pad_r'}.get(key,key)
    add('sample_load',path='/workspace/work/samples/'+fname+'.wav',instrument=inst,sample=0)
    add('instrument_set',instrument=inst,name={
        'kick':'Kick / Punch','snare':'Snare / Grit','clap':'Clap / Tail','ch':'Hat / Closed','oh':'Hat / Open','ride':'Ride / Metal','bass':'Bass / Analog','chord':'Chord / Detune','arp':'Arp / Pulse','lead':'Lead / Neon','padl':'Pad / Left','padr':'Pad / Right','pluck':'Pluck / Glass','riser':'FX / Riser','impact':'FX / Impact','tom':'Tom / Fill'}[key])
    vol={'kick':64,'snare':52,'clap':46,'ch':44,'oh':42,'ride':38,'bass':58,'chord':48,'arp':46,'lead':54,'padl':42,'padr':42,'pluck':46,'riser':42,'impact':54,'tom':52}[key]
    pan={'kick':128,'snare':116,'clap':140,'ch':98,'oh':164,'ride':176,'bass':128,'chord':128,'arp':164,'lead':128,'padl':48,'padr':208,'pluck':184,'riser':128,'impact':128,'tom':116}[key]
    add('sample_set',instrument=inst,sample=0,volume=vol,panning=pan,finetune=0,relative_note=0,loop_start=0,loop_length=0,flags=0,name=fname)
# Append note/effect calls after the setup calls.
# (The pattern functions above have already queued their calls; module_new was
# intentionally queued at the end only in this source, so reorder below.)
setup=calls[-(2+P+P+4*len(I)):]
# Actually compute prefix by the known marker instead of relying on arithmetic.
# All music calls precede the single module_new call.
idx=next(i for i,c in enumerate(calls) if c['name']=='module_new')
setup=calls[idx:]
music=calls[:idx]
calls=setup+music
with open('work/build.json','w') as f: json.dump(calls,f,separators=(',',':'))
print('calls',len(calls),'setup',len(setup),'music',len(music))
