import struct

def parse(p):
 b=open(p,'rb').read();hs=struct.unpack_from('<I',b,60)[0];nl,loop,ch,np,ni=struct.unpack_from('<HHHHH',b,64);off=60+hs
 for pi in range(np):
  hlen=struct.unpack_from('<I',b,off)[0]; rows,sz=struct.unpack_from('<HH',b,off+5);off+=hlen+sz
 print('\n',p,'patterns',np,'instruments',ni)
 for ii in range(ni):
  isize=struct.unpack_from('<I',b,off)[0];name=b[off+4:off+26];ns=struct.unpack_from('<H',b,off+27)[0];shsize=struct.unpack_from('<I',b,off+29)[0]
  vals=[]
  for j in range(ns):
   sh=off+isize+j*shsize
   L,ls,ll,vol,ft,fl,pan,rel=struct.unpack_from('<IIIbBBBb',b,sh)
   vals.append((L,ls,ll,vol,ft,fl,pan,rel))
   # skip sample data later handled below
  print(ii, isize, name.split(b'\0')[0], 'ns',ns,'samples',vals)
  off+=isize
  for j in range(ns):
   L=vals[j][0]; bits=16 if vals[j][5]&16 else 8;off+=L*(bits//8)
for p in ['work/rel_default.xm','submission/tune.xm']:parse(p)
PY"}

