import wave,numpy as np
with wave.open('work/preview8.wav','rb') as w:sr=w.getframerate();x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).astype(float)/32768
y=x.mean(1);d=np.abs(np.diff(y));
print('peak',np.max(np.abs(x)),'dc',np.mean(x,axis=0),'maxdiff',d.max(),'p99.9',np.percentile(d,99.9),'p99.99',np.percentile(d,99.99))
# top jumps and locations
for i in np.argsort(d)[-20:][::-1]:print(round(i/sr,3),round(d[i],4),round(y[i],4),round(y[i+1],4))
# silence runs > 20 ms after first 1s
mask=np.abs(y)<1e-5;runs=[];st=None
for i,v in enumerate(mask):
 if v and st is None:st=i
 if not v and st is not None:
  if i-st>441:runs.append((st/sr,(i-st)/sr))
  st=None
print('silence runs',runs[:20], 'n',len(runs))
