{"command":"python3 - <<'PY'
import wave,numpy as np
with wave.open('work/preview8.wav','rb') as w:sr=w.getframerate();x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).mean(1)/32768
# low-pass via FFT for P3 first bar to inspect bass gating
st=int(19.2*sr); y=x[st:st+int(1.6*sr)];f=np.fft.rfftfreq(len(y),1/sr);Y=np.fft.rfft(y);Y[(f<35)|(f>500)]=0;z=np.fft.irfft(Y,len(y));d=np.abs(np.diff(z));
print('bass-band maxdiff',d.max())
for off in [0,2,4,6,8,10,12,14]:
 t=off*.1; i=int(t*sr);print(off,'jump around',np.max(d[max(0,i-100):i+200]),'at',np.argmax(d[max(0,i-100):i+200])+max(0,i-100))
# actual waveform around a bass cut
for t in [19.2,19.4,19.6,19.8,20.0]:
 i=int(t*sr);print(t,z[i-10:i+10])
PY"}

